import re

from moler.cmd.commandtextualgeneric import CommandTextualGeneric
from moler.exceptions import CommandFailure
from moler.exceptions import ParsingDone


class SwmanShellCommand(CommandTextualGeneric):
    """Swmanshellcommand command class."""

    def __init__(self, connection, options, prompt=None, newline_chars=None, runner=None):
        """
        Execute sw inventory, sw save and sw activate requests.

        :param connection: moler connection to device, terminal when command is executed
        :param options:
        -i Executes software Inventory request
        -s <path/fileName> <fileVersion> Executes software Save request.
        -a <bldName> <bldVersion> <fileName> <fileVersion> Executes software Activate request.
        -c <cpid> Swman address. If option exist command doesn't ask syscon for a swman address
        :param prompt: Prompt of the starting shell
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(SwmanShellCommand, self).__init__(connection=connection, prompt=prompt, newline_chars=newline_chars,
                                                runner=runner)

        self.options = options
        self.keys = []

    def build_command_string(self):
        """
        Build command string.

        :return: String representation of command to send over connection to device.
        """
        return f"SWmanShellCommand {self.options}"

    def on_new_line(self, line, is_full_line):
        """
        Execute all parsing methods.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._parse_command_error(line)
                self._parse_command_failure(line)
                self._prepare_dict(line)
                self._parse_line(line)
            except ParsingDone:
                pass
        return super(SwmanShellCommand, self).on_new_line(line, is_full_line)

    _re_usage_info = re.compile(r"Executes\sSW\sInventory,\sSW\sSave\sand\sSW\sActivate\srequests", re.I)

    def _parse_command_error(self, line):
        if self._regex_helper.search_compiled(SwmanShellCommand._re_usage_info, line):
            self.set_exception(CommandFailure(self, "Wrong command syntax."))
            raise ParsingDone

    _re_operation_error = re.compile(r"Operation\sError:.*", re.I)

    def _parse_command_failure(self, line):
        if self._regex_helper.search_compiled(SwmanShellCommand._re_operation_error, line):
            self.set_exception(CommandFailure(self, "Wrong command syntax."))
            raise ParsingDone

    _re_dict = re.compile(r"(?P<KEY>[^:]+):\s+(?P<VALUE>.+)")

    def _parse_line_to_dict(self, line):
        if self._regex_helper.match_compiled(SwmanShellCommand._re_dict, line):
            return {self._regex_helper.group("KEY"): self._regex_helper.group("VALUE")}
        else:
            raise ParsingDone

    def _prepare_dict(self, line):
        if self._regex_helper.search(r"File\[\d+\]:", line) and "File" not in self.keys:
            self.current_ret.update({"File": {}})
            self.keys.append("File")
        if self._regex_helper.search(r"File\[(?P<FILE>\d+)\]:", line):
            file_nr = self._regex_helper.group("FILE")
            self.current_ret["File"].update({file_nr: {}})
            if len(self.keys) == 1:
                self.keys.append({"File_nr": file_nr})
            elif len(self.keys) == 2:
                self.keys[1]["File_nr"] = file_nr
            raise ParsingDone

    def _parse_line(self, line):
        if "File" in self.keys:
            self.current_ret["File"][self.keys[1]["File_nr"]].update(self._parse_line_to_dict(line))
            raise ParsingDone
        else:
            self.current_ret.update(self._parse_line_to_dict(line))
            raise ParsingDone


